def test_athena_known_function_kept(self):
        sql = "SELECT LISTAGG(x, ',') WITHIN GROUP (ORDER BY x) FROM t"
        self.assertEqual(
            render(sql, anonymize(sql, "athena"), "athena"),
            "SELECT LISTAGG(a, 'b') aaaaac aaaad (ORDER BY a) FROM e",
