def _alias(counter: int, text: str) -> str:
    digits = []
    while counter:
        counter, digit = divmod(counter, ALPHABET_SIZE)
        digits.append(ALPHABET[digit])

    letters = "".join(reversed(digits)).rjust(sum(not char.isspace() for char in text), "a")

    alias = []
    i = 0
    for char in text:
        if char.isspace():
            alias.append(char)
        else:
            alias.append(letters[i])
            i += 1

    return "".join(alias)

def _number_alias(counter: int, text: str) -> str:
    if len(text) > 4000:
        digits_seen = False
        blanked = []
        for char in text:
            if char.isdigit():
                blanked.append("0" if digits_seen else "1")
                digits_seen = True
            else:
                blanked.append(char)
        return "".join(blanked)

    sep = "e" if "e" in text else ("E" if "E" in text else "")
    mantissa, _, exponent = text.partition(sep) if sep else (text, "", "")
    sign = ""
    if exponent.startswith(("-", "+")):
        sign, exponent = exponent[0], exponent[1:]
    exponent_length = len(exponent)

    integer, dot, fraction = mantissa.partition(".")
    integer_length = len(integer)
    digits = integer_length + len(fraction)
    mantissa_value = 10 ** (digits - 1) + counter % (9 * 10 ** (digits - 1))
    result = str(mantissa_value)
    if dot:
        result = result[:integer_length] + "." + result[integer_length:]
    if sep:
        # The exponent marker is kept even when there are no digits after it, e.g. 1e
        result += sep + sign
        if exponent_length:
            exponent_value = 10 ** (exponent_length - 1) + (counter // (9 * 10 ** (digits - 1))) % (
                9 * 10 ** (exponent_length - 1)
            )
            result += str(exponent_value)

    return result

def _blank_comment(sql: str, i: int, start: str, end: str | None, nested: bool) -> tuple[str, int]:
    """Blanks the body of the comment at `i`, returning its text and the index past it."""
    body = i + len(start)

    if not end:
        stop = sql.find("\n", body)
        stop = len(sql) if stop == -1 else stop
        return start + _blank(sql[body:stop]), stop

    depth = 1
    j = body
    while j < len(sql):
        if nested and sql.startswith(start, j):
            depth += 1
            j += len(start)
        elif sql.startswith(end, j):
            j += len(end)
            depth -= 1
            if not depth:
                return start + _blank(sql[body : j - len(end)]) + end, j
        else:
            j += 1

    return start + _blank(sql[body:]), len(sql)

@classmethod
    def get_or_raise(cls, dialect: DialectType) -> Dialect:
        """
        Look up a dialect in the global dialect registry and return it if it exists.

        Args:
            dialect: The target dialect. If this is a string, it can be optionally followed by
                additional key-value pairs that are separated by commas and are used to specify
                dialect settings, such as whether the dialect's identifiers are case-sensitive.

        Example:
            >>> from sqlglot.dialects.dialect import Dialect
            >>> dialect = Dialect.get_or_raise("duckdb")
            >>> dialect = Dialect.get_or_raise("mysql, normalization_strategy = case_sensitive")

        Returns:
            The corresponding Dialect instance.
        """

        if not dialect:
            return cls()
        if isinstance(dialect, _Dialect):
            return dialect()
        if isinstance(dialect, Dialect):
            return dialect
        if isinstance(dialect, str):
            try:
                dialect_name, *kv_strings = dialect.split(",")
                kv_pairs = (kv.split("=") for kv in kv_strings)
                kwargs = {}
                for pair in kv_pairs:
                    key = pair[0].strip()
                    value: bool | str | None = None

                    if len(pair) == 1:
                        # Default initialize standalone settings to True
                        value = True
                    elif len(pair) == 2:
                        value = pair[1].strip()

                    kwargs[key] = to_bool(value)

            except ValueError:
                raise ValueError(
                    f"Invalid dialect format: '{dialect}'. "
                    "Please use the correct format: 'dialect [, k1 = v2 [, ...]]'."
                )

            result = cls.get(dialect_name.strip())
            if not result:
                # Include both built-in dialects and any loaded dialects for better error messages
                all_dialects = set(DIALECT_MODULE_NAMES) | set(cls._classes.keys())
                suggest_closest_match_and_fail("dialect", dialect_name, all_dialects)

            assert result is not None
            return result(**kwargs)

        raise ValueError(f"Invalid dialect type for '{dialect}': '{type(dialect)}'.")

