def _datetrunc_eq_expression(
    left: exp.Expr, drange: DateRange, target_type: exp.DataType | None
) -> exp.Expr:
    """Get the logical expression for a date range"""
    return exp.and_(
        left >= date_literal(drange[0], target_type),
        left < date_literal(drange[1], target_type),
        copy=False,
    )

def _parenthesize_nested_connector(expression: exp.Expr, parent: exp.Expr | None) -> exp.Expr:
    """
    The generator flattens nested connectors and relies on Paren nodes for grouping.
    Operator precedence varies across dialects, so wrap unless the parent is the same
    connector type, in which case flattening is safe by associativity.
    """
    if isinstance(expression, exp.Connector) and (
        isinstance(parent, exp.Not)
        or (isinstance(parent, exp.Connector) and type(parent) is not type(expression))
    ):
        return exp.paren(expression, copy=False)

    return expression

def extract_date(cast: exp.Expr) -> date | None:
    if isinstance(cast, exp.Cast):
        to = cast.to
    elif isinstance(cast, exp.TsOrDsToDate) and not cast.args.get("format"):
        to = exp.DType.DATE.into_expr()
    else:
        return None

    if isinstance(cast.this, exp.Literal):
        value: t.Any = cast.this.name
    elif isinstance(cast.this, (exp.Cast, exp.TsOrDsToDate)):
        value = extract_date(cast.this)
    else:
        return None
    return cast_value(value, to)

def extract_type(*expressions: exp.Expr):
    target_type = None
    for expression in expressions:
        target_type = expression.to if isinstance(expression, exp.Cast) else expression.type
        if target_type:
            break

    return target_type

def date_literal(date: object, target_type=None) -> exp.Expr:
    if not target_type or not target_type.is_type(*exp.DataType.TEMPORAL_TYPES):
        target_type = exp.DType.DATETIME if isinstance(date, datetime) else exp.DType.DATE

    return exp.cast(exp.Literal.string(date), target_type)

def datetime_floor(d: date, unit: str, dialect: Dialect) -> date:
    # Truncate sub-day units — only valid for datetime inputs
    if isinstance(d, datetime):
        if unit == "hour":
            return d.replace(minute=0, second=0, microsecond=0)
        elif unit == "minute":
            return d.replace(second=0, microsecond=0)
        elif unit == "second":
            return d.replace(microsecond=0)
        elif unit == "millisecond":
            return d.replace(microsecond=(d.microsecond // 1000) * 1000)
        elif unit == "microsecond":
            return d

    # Truncate date-level units, shared for both date and datetime
    if unit == "year":
        result: date = d.replace(month=1, day=1)
    elif unit == "quarter":
        if d.month <= 3:
            result = d.replace(month=1, day=1)
        elif d.month <= 6:
            result = d.replace(month=4, day=1)
        elif d.month <= 9:
            result = d.replace(month=7, day=1)
        else:
            result = d.replace(month=10, day=1)
    elif unit == "month":
        result = d.replace(month=d.month, day=1)
    elif unit == "week":
        # Week truncation respects dialect.WEEK_OFFSET (0=Monday, -1=Sunday)
        result = d - timedelta(days=(d.weekday() - dialect.WEEK_OFFSET) % 7)
    elif unit == "day":
        result = d
    else:
        raise UnsupportedUnit(f"Unsupported unit: {unit}")

    # For datetime inputs, zero out the time component after date-level truncation
    if isinstance(result, datetime):
        return result.replace(hour=0, minute=0, second=0, microsecond=0)
    return result

def _trunc_unit(unit: exp.Expr, dialect: Dialect) -> str:
    if isinstance(unit, exp.WeekStart):
        from sqlglot.dialects.dialect import WEEK_START_DAY_TO_DOW, week_offset_to_dow

        if WEEK_START_DAY_TO_DOW.get(unit.name.upper()) != week_offset_to_dow(dialect.WEEK_OFFSET):
            raise UnsupportedUnit(f"Unsupported unit: {unit}")
        return "week"

    return unit.name.lower()

def _is_negated(expression: exp.Expression) -> bool:
    parent = expression.parent
    while isinstance(parent, exp.Paren):
        parent = parent.parent
    return isinstance(parent, exp.Not)

def _other_operand(expression: object) -> exp.Expr | None:
    if isinstance(expression, exp.In):
        return expression.this

    if isinstance(expression, (exp.Any, exp.All)):
        return _other_operand(expression.parent)

    if isinstance(expression, exp.Binary):
        return (
            expression.right
            if isinstance(expression.left, (exp.Subquery, exp.Any, exp.Exists, exp.All))
            else expression.left
        )

    return None

